#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;
namespace IanGame.Editor {
public static class Phase31Verification {
 static LifeWorldController W=>GameContext.Instance.game.world.Host;
 internal static IEnumerator Wait(){float until=Time.unscaledTime+25;int stable=0;while(stable<4&&Time.unscaledTime<until){if(GameContext.Instance.transitions.IsTransitioning||W==null||W.Busy)stable=0;else stable++;yield return null;}if(stable<4)throw new Exception("Phase31 action/transition timeout");}
 internal static IEnumerator Shot(string name){Directory.CreateDirectory("Docs/Phase31/Screenshots");yield return new WaitForSecondsRealtime(.12f);ScreenCapture.CaptureScreenshot("Docs/Phase31/Screenshots/"+name+".png");yield return null;yield return null;}
 internal static IEnumerator Walk(Vector2 p,Action<bool,string> check,string name){W.Player.BeginTraversal(p,2.4f);float until=Time.unscaledTime+12;var frames=new HashSet<Sprite>();while(W.Player.IsTraversing&&Time.unscaledTime<until){frames.Add(W.Player.sprite.sprite);yield return null;}check(W.Player.TraversalArrived&&Vector2.Distance(W.Player.Position,p)<.06f,"Physical walk reaches "+name);W.Player.CancelTraversal();}
 static WorldInteractable Find(string id)=>W.GetComponentsInChildren<WorldInteractable>(true).First(o=>o.id==id&&o.isActiveAndEnabled);
 internal static IEnumerator Action(WorldInteractable o,int action,string food,Action<bool,string> check,string label){var d=o.GetComponent<WorldLifeAction>();yield return Walk(d.approach.position,check,label+" approach");check(W.CanControl&&W.IsInReach(o),"Control and reach before "+label);var g=W.Service.Game;double time=g.clock.ElapsedSeconds;check(W.Begin(o,action,food),"Existing action accepted "+label);check(!W.Begin(o,action,food),"Repeated input rejected "+label);W.hud.Notify("",2);float until=Time.unscaledTime+20;bool seen=false,bodyVisible=false,inside=false;var frames=new HashSet<Sprite>();while(W.Busy&&Time.unscaledTime<until){if(d.Ready){if(!seen){seen=true;yield return Shot(label);}bodyVisible|=W.Player.sprite.enabled;inside|=W.Player.growthVisual.Seated||W.Player.growthVisual.InBed;frames.Add(W.Player.sprite.sprite);}yield return null;}check(!W.Busy&&d.Completed,"Natural exit completed "+label);check(seen&&bodyVisible,"Actual player body remains visible "+label);check(frames.Count>(d.mode==LifeActionVisual.Bed?0:1),"Authored action frames rendered "+label);check(W.CanControl&&!W.Player.controlLocks.Locked&&W.Player.PoseName=="Idle","Input restored after "+label);check(o.GetComponent<WorldActivitySlot>()==null||o.GetComponent<WorldActivitySlot>().State==ActivityOccupancy.Free,"Occupancy released "+label);check(g.clock.ElapsedSeconds>time,"Existing service advances time for "+label);}
 public static IEnumerator Run(GameManager g,Action<bool,string> check,Action<GameObject,string> audit,string mode){
  if(mode=="roomVisualPhase31Extended"){yield return Phase31ExtendedVerification.Run(g,check);yield break;}
  g.growth.Restore(new ProgressSnapshot{age=19});g.clock.realtimeEnabled=false;g.clock.Restore(4,new TimeSnapshot{subDaySeconds=14*3600});var stats=g.stats.Capture();stats.money=20000;g.stats.Restore(stats);check(g.economy.MoveResidence("phase31/home","starter"),"Existing qualified independence path");var t=GameContext.Instance.transitions;check(t.NavigateRoom("home",t.roomCatalog.rules.Zone("home").spawn,Vector2.down),"Home scene requested");yield return Wait();W.Player.Warp(W.CurrentZone.origin+Vector2.down*.4f);W.follow.Snap();yield return new WaitForSecondsRealtime(.3f);
  if(mode.EndsWith("Before")){Directory.CreateDirectory("Docs/Phase31/Before");ScreenCapture.CaptureScreenshot("Docs/Phase31/Before/Home.png");yield return null;yield return null;yield break;}
  W.hud.Notify("",2);var player=W.Player;var bank=player.advanced.library;check(bank==UnityEditor.AssetDatabase.LoadAssetAtPath<ActorAnimationSet>("Assets/_Game/Data/Phase31/IanYoungAdultAnimations.asset"),"Young adult uses production animation bank: "+bank.name);check(player.growthVisual.BodyInteractions,"Adult uses body interaction path");check(player.presentation!=null&&player.controlLocks!=null,"Separated animation and owned control locks bound");
  foreach(var direction in (ActorDirection[])Enum.GetValues(typeof(ActorDirection))){check(bank.Find(ActorMotion.Idle,direction,false)!=null&&bank.Find(ActorMotion.Walk,direction,false)!=null,"Actual four-direction idle and walk "+direction);}
  var lease1=player.controlLocks.Acquire("qa/a");var lease2=player.controlLocks.Acquire("qa/b");lease1.Dispose();check(!W.CanControl&&player.controlLocks.OwnerCount==1,"One owner cannot release another input lock");lease2.Dispose();check(W.CanControl,"All owners released restores input");
  check(!W.GetComponentsInChildren<WorldInteractable>().Any(o=>o.name.StartsWith("Owned furniture")&&o.id!="basic-bed"),"Fresh independent house still starts with bed only");
  yield return Action(Find("bed"),5,"",check,"01-Sleep");yield return Shot("02-Wake");
  foreach(var id in new[]{"fridge","basic-table","desk","chair"}){check(g.economy.BuyFurniture("phase31/purchase/"+id,id),"Existing furniture purchase "+id);check(g.economy.FindFurniturePlacement(id,false,out var position,out var reason),"Valid existing layout slot "+id+" "+reason);check(g.economy.PlaceFurniture(id,position),"Existing furniture placement "+id);yield return null;yield return null;}
  g.world.State.rice=3;g.world.State.prepared="";int rice=g.world.State.rice;yield return Action(Find("fridge"),-1,"rice",check,"03-Fridge");check(g.world.State.rice==rice-1&&g.world.State.prepared=="rice","Fridge consumes ingredient once through original service");
  var before=g.stats.Capture();yield return Action(Find("basic-table"),3,"",check,"04-Meal");check(g.world.State.prepared=="","Meal actually consumes prepared food");
  var desk=Find("desk");check(desk.kind==WorldInteractionKind.Rest&&desk.GetComponent<WorldLifeAction>().restComputer,"Home computer uses existing rest action; school permissions remain unchanged");yield return Action(desk,1,"",check,"05-Computer");
  yield return Action(Find("chair"),1,"",check,"05B-Chair");yield return Shot("06-Furnished-Home");
  var destination=W.CurrentZone.origin+new Vector2(0,-2.2f);yield return Walk(destination,check,"clear floor");var portal=Find("front-door");yield return Walk(portal.Point,check,"front door");string outside=portal.targetZone;long cash=g.economy.Cash;check(W.Use(portal),"Original front door interaction accepted");yield return Wait();check(g.world.State.zone==outside,"Actual scene door exits to "+outside+" (actual "+g.world.State.zone+")");check(g.economy.Cash==cash&&g.growth.Age==19,"Door preserves age and cash");yield return Shot("07-Outside");
  var returnDoor=W.GetComponentsInChildren<WorldInteractable>().First(o=>o.kind==WorldInteractionKind.Door&&o.targetZone=="home");yield return Walk(returnDoor.Point,check,"return door");check(W.Use(returnDoor),"Return door interaction accepted");yield return Wait();check(g.world.State.zone=="home","Actual door returns home");yield return Shot("07B-Returned");check(W.Player.PoseName=="Idle"&&!W.Player.controlLocks.Locked,"Scene return resets transient visual/control state");
  g.growth.Restore(new ProgressSnapshot{age=0});yield return new WaitForSecondsRealtime(.7f);check(!W.Player.MovementAllowed&&W.Player.growthVisual.Current.stage==VisualGrowthStage.Newborn,"Newborn visual and walking restriction preserved");
  foreach(int age in new[]{1,6,7,12,13,18,19,29,30,59,60}){g.growth.Restore(new ProgressSnapshot{age=age});yield return new WaitForSecondsRealtime(.65f);check(W.Player.growthVisual.Current==W.Player.growthVisual.catalog.AtAge(age),"Derived growth visual "+age);check(W.Player.MovementAllowed&&(g.growth.IndependentOutdoorUnlocked==(age>=7)),"Independent walking/outdoor rules "+age);}
  g.growth.Restore(new ProgressSnapshot{age=19});yield return new WaitForSecondsRealtime(.7f);W.Player.Warp(W.Safe(W.CurrentZone,new Vector2(0,-1)));W.Player.Face(Vector2.down);check(g.items.DebugGive(g.items.catalog.starterHeadphone,1),"QA item fixture");check(g.items.Equipment.Equip("phase31/headphone",g.items.catalog.starterHeadphone,out var itemError),"Original equipment service equips headphone "+itemError);yield return new WaitForSecondsRealtime(.5f);W.hud.Notify("",2);check(W.Player.GetComponent<ItemAppearanceController>().HasRenderedOverride,"Equipped headphone renders real overlay art");var headphone=W.Player.GetComponentsInChildren<SpriteRenderer>().Single(r=>r.name=="Equipped headphone art");check(headphone.bounds.max.y<W.Player.sprite.bounds.min.y+W.Player.sprite.bounds.size.y*.75f,"Headphone stays at neck below face");yield return Shot("08-Equipment");
  string saveError;check(g.SaveAutomaticCheckpoint(out saveError),"Actual save checkpoint "+saveError);SaveData saved;check(g.saves.TryReadAutomatic(out saved,out saveError),"Actual save read "+saveError);g.RestoreState(saved);yield return Wait();check(W.Player.growthVisual.Current.stage==VisualGrowthStage.Adult&&g.items.Equipment.Current(EquipmentSlot.Headphone)==g.items.catalog.starterHeadphone,"Age and equipment restored from save");
  var bed=Find("bed");yield return Walk(bed.GetComponent<WorldLifeAction>().approach.position,check,"cancel bed approach");check(W.Begin(bed,5),"Cancellable sleep starts");yield return new WaitForSecondsRealtime(.15f);W.CancelAction();yield return Wait();check(W.CanControl&&!W.Player.controlLocks.Locked&&W.Player.sprite.enabled,"Cancel restores renderer, collider, ownership and input");
  check(UnityEngine.Object.FindObjectsByType<GameManager>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<WorldPlayerMotor>(FindObjectsSortMode.None).Length==1,"Scene return retains one manager and one player");audit(W.hud.gameObject,"Phase31 final HUD");yield return Shot("09-Final");
 }
}
}
#endif
